public class ArrayMinimum {
    public static void main(String[] args) {
        int[] numbers = {12, 45, 3, 89, 27, 56};
        int smallest = numbers[0];

        for (int n : numbers) {
            if (n < smallest) {
                smallest = n;
            }
        }

        System.out.println("Smallest number: " + smallest);
    }
}
